let value = Number(msg.payload);

if (msg.topic === "team8/sensor/temperature") {
    context.set("t8", value);
}

if (msg.topic === "team9/sensor/temperature") {
    context.set("t9", value);
}

let t8 = context.get("t8");
let t9 = context.get("t9");

if (t8 !== undefined && t9 !== undefined) {
    msg.payload = (t8 + t9) / 2;
    return msg;
}

return null;

let temp = parseFloat(msg.payload);
let lastSent = context.get("lastSent") || 0;

if (temp < 28 && (Date.now() - lastSent > 60000)) {
    context.set("lastSent", Date.now());

    msg.payload = {
        subject: "⚠️ Temperature Alert",
        text: `Temperature dropped below 28°C.\nCurrent value: ${temp} °C\n\nPlease switch ON the LED.`,
        temp: temp
    };

    return msg;
}

return null;

let temp = flow.get("temp") || 0;
let hum = flow.get("hum") || 0;

if (msg.topic === "team9/sensor/temperature") {
    temp = Number(msg.payload);
    flow.set("temp", temp);
}

if (msg.topic === "team9/sensor/humidity") {
    hum = Number(msg.payload);
    flow.set("hum", hum);
}

msg.payload = {
    temp: temp,
    hum: hum
};

return msg;

const map = {
    red:    { on: "on1", off: "off1" },
    yellow: { on: "on2", off: "off2" },
    blue:   { on: "on3", off: "off3" },
    green:  { on: "on4", off: "off4" }
};

let color = msg.req.params.color;
let state = msg.req.params.state;

if (!map[color]) {
    msg.statusCode = 400;
    return [null, msg];
}

msg.payload = map[color][state];
msg.topic = "team9/LED";

return [msg, {statusCode:204}];

msg.temp = flow.get("temp") || "0";
msg.hum  = flow.get("hum")  || "0";

msg.tPct = Math.min(100, Math.round((parseFloat(msg.temp)/50)*100));
msg.hPct = Math.min(100, Math.round(parseFloat(msg.hum)));

return msg;

let temp = Number(msg.payload);

if(temp >= 22 && temp <= 28){
    msg.payload = "✅ HEALTHY";
}
else if(temp > 28 && temp <= 35){
    msg.payload = "⚠ WARNING";
}
else{
    msg.payload = "🚨 CRITICAL";
}

return msg;

let hum = Number(msg.payload);

if(hum >= 40 && hum <= 60){
    msg.payload = "✅ NORMAL";
}
else{
    msg.payload = "⚠ UNHEALTHY";
}

return msg;

let count = context.get('count') || 0;

count++;

context.set('count', count);

if(count > 5){
